  min-height: 100vh;
  padding: 20px;
}

.container {
  max-width: 600px;
  margin: 0 auto;
  padding: 40px 30px;
  background: rgba(30, 30, 46, 0.95);
  border-radius: 12px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(10px);
}

h1 {
  font-size: 2.5rem;
  margin-bottom: 30px;
  color: #64b5f6;
  font-weight: 600;
  letter-spacing: -0.5px;
}

.form-field {
  margin-bottom: 32px;
}

fieldset {
  border: none;
  padding: 0;
  margin: 0;
}

legend {
  font-size: 1.2rem;
  font-weight: 600;
  color: #90caf9;
  margin-bottom: 16px;
  display: block;
  padding: 0;
}

.help-text {
  font-size: 0.95rem;
  color: #b0bec5;
  margin-bottom: 12px;
  font-style: italic;
}

.checkbox-wrapper {
  display: flex;
  align-items: center;
  margin-bottom: 14px;
  padding: 8px;
  border-radius: 6px;
  transition: background-color 0.2s ease;
}

.checkbox-wrapper:focus-within {
  background-color: rgba(100, 181, 246, 0.1);
}

input[type="checkbox"] {
  width: 20px;
  height: 20px;
  margin-right: 12px;
  cursor: pointer;
  accent-color: #64b5f6;
  flex-shrink: 0;
  border-radius: 4px;
}

input[type="checkbox"]:focus {
  outline: 3px solid #64b5f6;
  outline-offset: 2px;
}

input[type="checkbox"]:focus-visible {
  outline: 3px solid #64b5f6;
  outline-offset: 2px;
}

label {
  font-size: 1.05rem;
  color: #e0e0e0;
  cursor: pointer;
  user-select: none;
  transition: color 0.2s ease;
}

input[type="checkbox"]:hover + label {
  color: #64b5f6;
}

input[type="checkbox"]:checked + label {
  color: #64b5f6;
  font-weight: 500;
}

.submit-button {
  width: 100%;
  padding: 14px 24px;
  margin-top: 24px;
  background: linear-gradient(135deg, #64b5f6 0%, #42a5f5 100%);
  color: #000;
  border: none;
  border-radius: 8px;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: 0 4px 15px rgba(100, 181, 246, 0.3);
}

.submit-button:hover {
  background: linear-gradient(135deg, #42a5f5 0%, #2196f3 100%);
  box-shadow: 0 6px 20px rgba(100, 181, 246, 0.5);
  transform: translateY(-2px);
}

.submit-button:active {
  transform: translateY(0);
  box-shadow: 0 2px 10px rgba(100, 181, 246, 0.3);
}

.submit-button:focus {
  outline: 3px solid #64b5f6;
  outline-offset: 2px;
}

.submit-button:focus-visible {
  outline: 3px solid #64b5f6;
  outline-offset: 2px;
}

#results {
  margin-top: 30px;
  padding: 20px;
  border-radius: 8px;
  background: rgba(100, 181, 246, 0.1);
  border-left: 4px solid #64b5f6;
}

#results.success {
  background: rgba(76, 175, 80, 0.1);
  border-left-color: #4caf50;
  color: #81c784;
}

#results.error {
  background: rgba(255, 87, 34, 0.1);
  border-left-color: #ff5722;
  color: #ff7043;
}

/* High contrast mode support */
@media (prefers-contrast: more) {
  legend {
    color: #ffffff;
  }

  label {
    color: #ffffff;
  }

  h1 {
    color: #ffffff;
  }

  input[type="checkbox"]:focus,
  input[type="checkbox"]:focus-visible {
    outline-width: 4px;
  }

  .submit-button:focus,
  .submit-button:focus-visible {
    outline-width: 4px;
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Responsive design */
@media (max-width: 480px) {
  .container {
    padding: 24px 16px;
  }

  h1 {
    font-size: 2rem;
  }

  legend {
    font-size: 1.05rem;
  }

  label {
    font-size: 1rem;
  }

  .submit-button {
    padding: 12px 20px;
    font-size: 1rem;
  }
}
