    q3: Array.from(document.querySelectorAll('input[name="q3"]:checked')).map(el => el.value)
  };

  // Calculate score
  let correctCount = 0;
  const totalQuestions = 3;

  for (let q in correctAnswers) {
    const correct = correctAnswers[q].sort().join(',');
    const userAnswer = userAnswers[q].sort().join(',');
    if (correct === userAnswer) {
      correctCount++;
    }
  }

  // Display results
  const resultsDiv = document.getElementById('results');
  const percentage = Math.round((correctCount / totalQuestions) * 100);

  let resultHTML = `<h2>Quiz Complete</h2><p>You scored ${correctCount} out of ${totalQuestions} (${percentage}%)</p>`;

  if (percentage === 100) {
    resultHTML += '<p>Perfect! You have excellent knowledge of computer languages. 🎉</p>';
    resultsDiv.className = 'success';
  } else if (percentage >= 67) {
    resultHTML += '<p>Great job! You got most of them right.</p>';
    resultsDiv.className = 'success';
  } else if (percentage >= 34) {
    resultHTML += '<p>Good effort! Review the explanations below.</p>';
    resultsDiv.className = '';
  } else {
    resultHTML += '<p>Keep learning! Review the explanations below.</p>';
    resultsDiv.className = 'error';
  }

  resultHTML += '<details style="margin-top: 16px;"><summary>Correct Answers</summary><ul style="margin-top: 12px; margin-left: 20px;">';
  resultHTML += '<li><strong>Question 1:</strong> Python, JavaScript (dynamically typed)</li>';
  resultHTML += '<li><strong>Question 2:</strong> C++, Rust (compiled languages)</li>';
