const path = require('path');
const axeSource = require('axe-core').source;

(async () => {
  const htmlFile = path.join(__dirname, 'index.html');
  const html = fs.readFileSync(htmlFile, 'utf8');

  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'load' });

  // Inject axe-core and run
  await page.evaluate(axeSource);
  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  console.log('Total violations:', results.violations.length);
  console.log('Passes:', results.passes.length);
  console.log('Incomplete:', results.incomplete.length);

  // Separate WCAG violations from best-practice
  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  if (wcag.length > 0) {
    console.log('\\n=== WCAG VIOLATIONS ===');
    wcag.forEach(v => {
      console.log('ID:', v.id, 'Impact:', v.impact);
      console.log('Description:', v.description);
      console.log('Targets:', v.nodes.map(n => n.target));
    });
  }

  if (bp.length > 0) {
    console.log('\\n=== BEST-PRACTICE WARNINGS ===');
    bp.forEach(v => {
      console.log('ID:', v.id);
      console.log('Description:', v.description);
      console.log('Targets:', v.nodes.map(n => n.target));
    });
  }

  if (wcag.length === 0 && bp.length === 0) {
    console.log('\\n✓ All checks passed! No WCAG violations or best-practice warnings.');
  }
})();
